html:
{# =======================
  BASIC SETUP
  - Replace logo path if needed
  - Map doc fields as per your Loan Application doctype
======================= #}

{% set base_url = frappe.utils.get_url() %}

{# doc.applicant holds Employee ID #}
{% set emp_key = doc.applicant or "" %}

{# Fetch employee data (single query) #}
{% set emp_data = frappe.db.get_value(
  "Employee",
  emp_key,
  ["name","employee_name","designation","department","date_of_joining","current_address","cell_number","cnic","reports_to"],
  as_dict=True
) if emp_key else None %}

{# Fetch HOD/Line Manager #}
{% set hod_name = "" %}
{% if emp_data and emp_data.reports_to %}
  {% set hod_name = frappe.db.get_value("Employee", emp_data.reports_to, "employee_name") or "" %}
{% endif %}

{% if emp_data %}
  {# emp_data.name is Employee.name (HR-EMP-xxxxx) #}
  {% set hod_id = frappe.db.get_value("Employee", emp_data.name, "reports_to") %}
  {% set hod_name = frappe.db.get_value("Employee", hod_id, "employee_name") if hod_id else "" %}
{% endif %}




{# COO / CEO (designation contains COO/CEO) #}
{% set coo = frappe.db.get_value("Employee", {"designation": ["like", "%Chief Operating Officer%"], "status":"Active"}, "employee_name") %}
{% set ceo = frappe.db.get_value("Employee", {"designation": ["like", "%Chief Executive Officer%"], "status":"Active"}, "employee_name") %}

<style>
  @page { size: A4; margin: 12mm; }
  .print-format { font-family: Arial, sans-serif; font-size: 11px; color:#000; }

  .frame{
    border:2px solid #000;
    padding:0;
  }

  .header-top{
    display:flex;
    align-items:center;
    justify-content:center;
    gap:10px;
    padding:10px 12px 6px;
    border-bottom:2px solid #000;
    font-weight:700;
    font-size:16px;
  }
  .logo{
    width:34px; height:34px; object-fit:contain;
  }

  .bar{
    background:#000;
    color:#fff;
    text-align:center;
    padding:6px 10px;
    font-weight:700;
    font-size:12px;
    letter-spacing:.2px;
  }

  .section{
    padding:10px 12px 12px;
  }

  .label{
    font-weight:700;
    font-size:10px;
  }

  .row{
    display:flex;
    gap:12px;
    margin-top:8px;
    align-items:flex-end;
    flex-wrap:wrap;
  }
  .cell{
    flex:1;
    min-width: 160px;
  }

  .line{
    border-bottom:1px solid #000;
    min-height:14px;
    padding:0 4px 1px;
    white-space:nowrap;
    overflow:hidden;
    text-overflow:ellipsis;
  }

  .line.big{ min-height:18px; }
  .cell.w120{ flex:0 0 120px; min-width:120px; }
  .cell.w160{ flex:0 0 160px; min-width:160px; }
  .cell.w200{ flex:0 0 200px; min-width:200px; }
  .cell.w260{ flex:0 0 260px; min-width:260px; }

  .divider{
    border-top:2px solid #000;
  }

  .two-sigs{
    display:flex;
    justify-content:space-between;
    margin-top:20px;
    gap:20px;
  }
  .sig{
    flex:1;
    font-size:10px;
  }
  .sig .sigline{
    border-bottom:1px solid #000;
    height:18px;
    margin-top:22px;
  }

  .official{
    padding:10px 12px 12px;
  }

  table.grid{
    width:100%;
    border-collapse:collapse;
    table-layout:fixed;
    margin-top:8px;
    font-size:10px;
  }
  table.grid td, table.grid th{
    border:1px solid #000;
    padding:6px 6px;
    vertical-align:middle;
  }
  .muted{ font-weight:700; }
  .line-inline{
    border-bottom:1px solid #000;
    display:inline-block;
    min-width:160px;
    height:14px;
    vertical-align:bottom;
  }

  .approve-row{
    text-align:center;
    margin-top:10px;
    font-size:10px;
    font-weight:700;
  }

  .bottom-sigs{
    display:flex;
    justify-content:space-between;
    gap:25px;
    margin-top:18px;
  }
  .bs{
    flex:1;
    text-align:center;
    font-size:10px;
    font-weight:700;
  }
  .bs .bline{
    border-bottom:1px solid #000;
    height:18px;
    margin:18px 20px 6px;
  }

  .header-wrap{
    display:flex;
    align-items:center;
    justify-content:center;
    gap:14px;
    margin-bottom:10px;
  }

  .logo-box{
    width:70px;
    height:70px;
    display:flex;
    align-items:center;
    justify-content:center;
    background:#fff;
    border:1px solid #000;
    border-radius:4px;
    overflow:hidden;
  }

  .logo-box img{
    max-width:100%;
    max-height:100%;
  }

  .company-title{
    text-align:center;
    line-height:1.2;
  }

  .company-title h2{
    margin:0;
    font-size:18px;
    font-weight:800;
    text-transform:uppercase;
    letter-spacing:.6px;
  }

  .company-title .tagline{
    font-size:10px;
    opacity:.8;
    text-transform:uppercase;
  }
</style>


<div class="header-wrap">
  <div class="logo-box">
    <img src="https://erp.theilmfoundation.cloud/files/454985247_461775626827401_330977418181804304_n.jpg">
  </div>

  <div class="company-title">
    <h2>THE ILM FOUNDATION</h2>
    <div class="tagline">Excellence Through Education</div>
  </div>
</div>


<div class="frame">


  <div class="bar">(Loan Application Form)</div>

  <!-- Applicant Use -->
  <div class="section">
    <div class="label">[For applicant use]:</div>

    <div class="row">
      <div class="cell w260">
        <div class="label">Name:</div>
        <div class="line">{{ doc.applicant }}</div>
      </div>
{% set emp = doc.employee or doc.applicant_employee or "" %}

{# emp can be employee name OR employee code - handle both #}
{% set emp_key = doc.applicant or doc.applicant_employee or doc.custom_employee or "" %}

{# 1) Try by Employee.name #}
{% set emp_data = frappe.db.get_value(
  "Employee",
  emp_key,
  ["employee_name", "designation", "department", "date_of_joining", "current_address", "cell_number", "cnic"],
  as_dict=True
) %}

{# 2) If not found, try by employee field (Employee Code / Employee Number) #}
{% if not emp_data and emp_key %}
  {% set emp_data = frappe.db.get_value(
    "Employee",
    {"employee": emp_key},
    ["employee_name", "designation", "department", "date_of_joining", "current_address", "cell_number", "cnic"],
    as_dict=True
  ) %}
{% endif %}


<div class="cell w200">
  <div class="label">Designation:</div>
  <div class="line">{{ emp_data.designation if emp_data else "" }}</div>
</div>

<div class="cell w200">
  <div class="label">Department:</div>
  <div class="line">{{ emp_data.department if emp_data else "" }}</div>
</div>
<div class="cell w200">
  <div class="label">Department:</div>
  <div class="line">
    {{ emp_data.department if emp_data else "" }}
  </div>
</div>
      <div class="cell w160">
        <div class="label">Date:</div>
        <div class="line">
          {{ frappe.utils.formatdate(doc.posting_date or doc.application_date or frappe.utils.nowdate()) }}
        </div>
      </div>
    </div>

    <div class="row">
      <div class="cell w260">
        <div class="label">Date of joining:</div>
        <div class="line">
          {% if emp_data.date_of_joining %}{{ frappe.utils.formatdate(emp_data.date_of_joining) }}{% endif %}
        </div>
      </div>

      <div class="cell w200">
        <div class="label">Leaves availed:</div>
        <div class="line">{{ doc.custom_leaves_availed or "" }}</div>
      </div>

      <div class="cell w200">
        <div class="label">Previous Loan:</div>
        <div class="line">{{ doc.custom_previous_loan or "" }}</div>
      </div>
    </div>

    <div class="row">
      <div class="cell">
        <div class="label">Details of Previous Loan:</div>
        <div class="line big">{{ doc.custom_details_of_previous_loan or "" }}</div>
      </div>
    </div>

    <div class="row">
      <div class="cell w260">
        <div class="label">Loan Applied for Rs:</div>
        <div class="line">{{ doc.loan_amount or doc.amount or "" }}</div>
      </div>

      <div class="cell">
        <div class="label">(Rupees):</div>
        <div class="line">
  {% if doc.loan_amount or doc.amount %}
    {{ frappe.utils.money_in_words(doc.loan_amount or doc.amount) }}
  {% endif %}
</div>
      </div>
    </div>

    <div class="row">
      <div class="cell">
        <div class="label">Reason:</div>
        <div class="line big">{{ doc.reason or doc.description or "" }}</div>
      </div>
    </div>

    <div class="row">
      <div class="cell w260">
        <div class="label">Deduction of Loan per month Rs:</div>
        <div class="line">{{ doc.repayment_amount or doc.repayment_amount or "" }}</div>
      </div>

      <div class="cell">
        <div class="label">(Rupees):</div>
        <div class="line">
  {% if doc.loan_amount or doc.amount %}
    {{ frappe.utils.money_in_words(doc.repayment_amount or doc.repayment_amount) }}
  {% endif %}
</div>
      </div>
    </div>

    <div class="row">
      <div class="cell">
        <div class="label">Address:</div>
        <div class="line">{{ emp_data.current_address or "" }}</div>
      </div>
    </div>

    <div class="row">
      <div class="cell w260">
        <div class="label">Contact No:</div>
        <div class="line">{{ emp_data.cell_number or "" }}</div>
      </div>

      <div class="cell w260">
        <div class="label">N.I.C #:</div>
        <div class="line">{{ emp_data.cnic or doc.cnic or "" }}</div>
      </div>
    </div>

   {% set today = frappe.utils.formatdate(frappe.utils.nowdate()) %}
{% set applicant_name = emp_data.employee_name if emp_data else (doc.applicant or "") %}

<div class="two-sigs">

  <!-- Applicant -->
  <div class="sig">
    Applicant’s Signature and Date
    <div class="sigline"></div>
    <div style="margin-top:4px; font-weight:700;">
      {{ applicant_name }}<br>
      {{ today }}
    </div>
  </div>

  <!-- HOD -->
  <div class="sig" style="text-align:right;">
    HOD Signature and Date
    <div class="sigline"></div>
    <div style="margin-top:4px; font-weight:700;">
      {{ hod_name or "" }}<br>
      {{ today }}
    </div>
  </div>

</div>


  </div>

  <div class="divider"></div>

  <!-- Official Use -->
  <div class="official">
    <div class="label">[For Official Use]:</div>

    <table class="grid">
      <tr>
        <td><span class="muted">Current Salary:</span> Rs. {{ doc.custom_current_salary or "" }}</td>
        <td><span class="muted">Leave Encashment:</span> Rs. {{ doc.custom_leave_encashment or "" }}</td>
        <td><span class="muted">Any Outstanding:</span> Rs. {{ doc.custom_any_outstanding or "" }}</td>
      </tr>
      <tr>
        <td><span class="muted">Gratuity:</span> Rs. {{ doc.custom_gratuity or "" }}</td>
        <td><span class="muted">Bonus:</span> Rs. {{ doc.custom_bonus or "" }}</td>
        <td><span class="muted">Available Balance:</span> Rs. {{ doc.custom_available_balance or "" }}</td>
      </tr>
    </table>

    <div class="row" style="margin-top:10px;">
      <div class="cell">
        <div class="label">Remarks:</div>
        <div class="line big">{{ doc.remarks or "" }}</div>
      </div>
    </div>

    <div class="row" style="margin-top:10px;">
      <div class="cell w260">
        <div class="label">Loan Sanction of Rs:</div>
        <div class="line">{{ doc.custom_loan_sanction or "" }}</div>
      </div>
      <div class="cell w260">
        <div class="label">Monthly Deduction of Rs:</div>
        <div class="line">{{ doc.custom_monthly_deduction or "" }}</div>
      </div>
    </div>

   <div class="approve-row">
  Approved 
  {% if doc.status == "Approved" %}
    ●
  {% else %}
    ○
  {% endif %}
  /

  Rejected 
  {% if doc.status == "Rejected" %}
    ●
  {% else %}
    ○
  {% endif %}
</div>

    <div class="bottom-sigs">
      <div class="bs">
        <div class="bline"></div>
        (COO)<br>{{ (coo or "") | upper }}
      </div>
      <div class="bs">
        <div class="bline"></div>
        (CEO)<br>{{ (ceo or "") | upper }}
      </div>
    </div>

  </div>
</div>
